<script setup>
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {api} from '../lib/api'
import {useMessages} from '../stores/messages'
defineProps({classes:{type:Array,default:()=>[]}})
const messages=useMessages(),search=ref(''),classId=ref(''),status=ref(''),items=ref([]),selected=ref(null),reply=ref(''),loading=ref(false),sending=ref(false),error=ref(''),success=ref('');let requestKey=crypto.randomUUID(),interval,alive=true,detailRequest=0
watch(reply,()=>{if(!sending.value)requestKey=crypto.randomUUID()},{flush:'sync'})
async function load(){if(loading.value)return;loading.value=true;try{const result=await api('/admin/messages?'+new URLSearchParams({search:search.value,classId:classId.value,status:status.value}));if(alive){items.value=result.items;messages.pending=result.pending}}catch(e){if(alive)error.value=e.message}finally{if(alive)loading.value=false}}
async function open(id){const current=++detailRequest;error.value='';success.value='';try{const item=await api('/admin/messages/'+id);if(alive&&current===detailRequest){selected.value=item;reply.value='';requestKey=crypto.randomUUID()}}catch(e){if(alive)error.value=e.message}}
async function send(){if(sending.value||!selected.value||!reply.value.trim())return;sending.value=true;error.value='';success.value='';const id=selected.value.id;try{await api('/admin/messages/'+id+'/reply',{method:'POST',body:{content:reply.value,requestKey}});success.value='학생에게 답장을 보냈어요.';reply.value='';requestKey=crypto.randomUUID();selected.value=await api('/admin/messages/'+id);await load();await messages.refresh()}catch(e){error.value=e.message}finally{sending.value=false}}
const composing=ref(false),recipients=ref([]),recipientSearch=ref(''),recipientId=ref(''),newTitle=ref(''),newContent=ref('');let composeKey=crypto.randomUUID()
async function findRecipients(){try{recipients.value=(await api('/admin/message-recipients?'+new URLSearchParams({search:recipientSearch.value}))).items}catch(e){error.value=e.message}}
async function compose(){composing.value=true;await findRecipients()}
watch([recipientId,newTitle,newContent],()=>{if(!sending.value)composeKey=crypto.randomUUID()},{flush:'sync'})
async function sendNew(){if(sending.value)return;sending.value=true;error.value='';try{await api('/admin/messages',{method:'POST',body:{studentId:recipientId.value,title:newTitle.value,content:newContent.value,requestKey:composeKey}});composing.value=false;newTitle.value='';newContent.value='';composeKey=crypto.randomUUID();success.value='학생에게 쪽지를 보냈어요.';await load();await messages.refresh()}catch(e){error.value=e.message}finally{sending.value=false}}
async function remove(id){if(sending.value||!window.confirm('내 쪽지함에서 삭제할까요? 상대방의 쪽지는 유지됩니다.'))return;sending.value=true;try{await api('/admin/messages/'+id,{method:'DELETE'});if(selected.value?.id===id)selected.value=null;success.value='내 쪽지함에서 삭제했어요.';await load();await messages.refresh()}catch(e){error.value=e.message}finally{sending.value=false}}
async function clearAll(){if(sending.value||!window.confirm('검색 조건과 관계없이 내 학생 쪽지함을 모두 삭제할까요? 학생들의 쪽지는 유지됩니다.'))return;sending.value=true;error.value='';try{await api('/admin/messages',{method:'DELETE',body:{confirmed:true}});detailRequest++;selected.value=null;success.value='내 학생 쪽지함을 모두 삭제했어요.';await load();await messages.refresh()}catch(e){error.value=e.message}finally{sending.value=false}}
function poll(){if(document.visibilityState==='visible')load()}
onMounted(()=>{load();interval=setInterval(poll,15000);document.addEventListener('visibilitychange',poll)})
onUnmounted(()=>{alive=false;detailRequest++;clearInterval(interval);document.removeEventListener('visibilitychange',poll)})
</script>
<template><section class="panel study-history admin-mailbox"><div class="mailbox-heading"><h2>학생 쪽지함</h2><b class="mail-count">답변 대기 {{messages.pending}}개</b><button class="light mail-clear-all" :disabled="sending||loading" @click="clearAll">학생 쪽지 전체 삭제</button></div><p>학생과 관리자만 확인하는 비공개 쪽지입니다.</p><button class="light" @click="compose">＋ 학생에게 쪽지 쓰기</button><form v-if="composing" class="admin-compose" @submit.prevent="sendNew"><h3>학생에게 새 쪽지</h3><label>받는 학생 검색<input v-model="recipientSearch" maxlength="100" @input="findRecipients" placeholder="이름 또는 아이디"/></label><label>받는 학생<select v-model="recipientId" required><option disabled value="">학생 선택</option><option v-for="u in recipients" :key="u.id" :value="u.id">{{u.name}} · {{u.login}} · {{u.class_name}}</option></select></label><label>제목<input v-model="newTitle" required maxlength="100"/></label><label>내용<textarea v-model="newContent" required maxlength="5000" rows="4"/></label><div class="toolbar"><button :disabled="sending||!recipientId||!newTitle.trim()||!newContent.trim()">{{sending?'전송 중…':'학생에게 보내기'}}</button><button type="button" class="light" @click="composing=false">닫기</button></div></form><form class="mail-filters" @submit.prevent="load"><label>학생명·아이디<input v-model="search" maxlength="100" placeholder="학생 검색"/></label><label>기수<select v-model="classId"><option value="">전체 기수</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>답변 상태<select v-model="status"><option value="">전체 상태</option><option value="pending">답변 대기</option><option value="answered">답변 완료</option></select></label><button :disabled="loading">{{loading?'불러오는 중…':'쪽지 검색'}}</button></form><p v-if="error" class="account-error" role="alert">{{error}}</p><p v-if="success" class="mail-success" role="status">{{success}}</p><p v-if="!items.length&&!loading">조건에 맞는 쪽지가 없어요.</p><div v-for="m in items" :key="m.id" class="mail-list-item"><div class="mail-meta"><b>{{m.student_name}} · {{m.class_name}}</b><span class="review-badge">{{m.status==='answered'?'답변 완료':'답변 대기'}}</span></div><button class="mail-subject-link" :disabled="sending" @click="open(m.id)">{{m.title}} →</button><button class="text-button mail-delete" :disabled="sending" @click="remove(m.id)">삭제</button><time>{{new Date(m.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</time></div><section v-if="selected" class="mail-admin-detail"><button class="text-button" :disabled="sending" @click="selected=null">쪽지 상세 닫기</button><button class="text-button mail-delete" :disabled="sending" @click="remove(selected.id)">쪽지 삭제</button><h3>{{selected.title}}</h3><p>{{selected.studentName}} ({{selected.className}})</p><p v-if="!selected.fromAdmin" class="mail-body">{{selected.body}}</p><article v-for="r in selected.replies" :key="r.id" class="mail-reply"><p><b>{{r.admin_name}} {{r.senderRole==='student'?'학생':'관리자'}}</b> · {{r.read_at?'학생 읽음':'학생 읽지 않음'}} · {{new Date(r.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</p><p class="mail-body">{{r.body}}</p></article><form @submit.prevent="send"><label for="admin-mail-reply">학생에게 답장</label><textarea id="admin-mail-reply" v-model="reply" :disabled="sending" required maxlength="5000" rows="6" placeholder="학생에게 보낼 답장을 적어 주세요."/><button :disabled="sending||!reply.trim()">{{sending?'답장 전송 중…':'답장 전송'}}</button></form></section></section></template>
